update public.learning_paths
set
  title = 'Research Methods in Criminal Justice',
  goal = 'Research Methods in Criminal Justice',
  summary = 'Frame criminal justice research as systematic inquiry into crime, victimization, policing, courts, corrections, communities, and public policy. Students turn justice problems into researchable questions grounded in theory and prior evidence, protect people, communities, records, and institutions, and learn how design, measurement, and sampling shape credible claims. Topics cover surveys and victimization research, qualitative interviews and ethnography, field observation and agency research, experiments and program evaluation, official records, descriptive and inferential statistics, regression and introductory causal inference, mixed methods, reproducible workflows, equity and responsible analytics, and research reporting.',
  data = $rmcjjson${"slug": "research-methods-in-criminal-justice", "title": "Research Methods in Criminal Justice", "description": "Frame criminal justice research as systematic inquiry into crime, victimization, policing, courts, corrections, communities, and public policy. Students turn justice problems into researchable questions grounded in theory and prior evidence, protect people, communities, records, and institutions, and learn how design, measurement, and sampling shape credible claims. Topics cover surveys and victimization research, qualitative interviews and ethnography, field observation and agency research, experiments and program evaluation, official records, descriptive and inferential statistics, regression and introductory causal inference, mixed methods, reproducible workflows, equity and responsible analytics, and research reporting.", "topics": [{"id": "6f633abe-04fa-449f-b45d-759fae5a8b28", "type": "topic", "title": "Criminal Justice Research, Scientific Inquiry, and Evidence", "description": "Frame criminal justice research as systematic inquiry into crime, victimization, policing, courts, corrections, communities, and public policy.", "children": [{"id": "fe5af87d-47e2-4115-a974-b783717ce156", "type": "subtopic", "title": "Scientific method in criminal justice", "children": [{"id": "64898c85-bb64-46a0-bbb0-35f7cd9d5b83", "type": "concept", "title": "Observation"}, {"id": "ca3d35c7-bce4-4016-b840-7de08b038070", "type": "concept", "title": "Theory"}, {"id": "b6ec9977-e7be-40f8-ae61-9f054080701c", "type": "concept", "title": "Hypothesis"}, {"id": "9f63d1de-242a-4b94-ba27-12d6211ab0e3", "type": "concept", "title": "Evidence and revision"}], "description": "The scientific method makes justice claims testable, transparent, and open to revision."}, {"id": "d7137885-3ce6-48c1-8976-c001cc8f6e9d", "type": "subtopic", "title": "What criminal justice researchers study", "children": [{"id": "fe6ebb4d-a7d0-489c-9e7c-068135cdb8a6", "type": "concept", "titl